    std::vector<Student> classList = {{"Bob", 85}, {"Alice", 95}, {"Charlie", 78}};

    // Sort students by score descending
    std::sort(classList.begin(), classList.end(), [](const Student &a, const Student &b) {
        return a.score > b.score;
    });

